{
  "description": "A single quadrupedal mammal shown in right-facing profile against a plain light background, with an arched back and body held low on four stout limbs. The animal has an elongated tapered snout, a small rounded ear, and a long thick tapering tail resting on the ground behind it. Most of the dorsal surface, the top of the head, the outer sides of the limbs, and the tail are covered in overlapping dark brown to gray keratinous scales with lighter edges and fine ridged texture. Large irregular patches of pale pink, wrinkled bare skin are exposed where scales are absent on the mid-back, the mid-flank above the foreleg, and the lower rump and inner hindquarter. The ventral surface and lower limbs show pale gray-brown skin, and the feet bear long curved dark claws. The overall posture is standing/walking with all four feet in contact with the ground.",
  "parts": [
    {
      "part": "head",
      "looks_like": "elongated and narrow with a pointed snout ending in a dark nostril, gray-brown wrinkled skin on the sides, a dark round glossy eye with fine lashes, and small overlapping scales covering the crown and bridge of the snout",
      "where": "at the front right end of the body, projecting forward"
    },
    {
      "part": "ears",
      "looks_like": "one small rounded ear with a folded helix and fine pale hairs around the rim, gray-brown skin",
      "where": "on the side of the head just behind and slightly above the eye"
    },
    {
      "part": "eyes",
      "looks_like": "one visible dark round eye with a distinct eyelid and short eyelashes, glossy",
      "where": "on the side of the head below the scaled crown and in front of the ear"
    },
    {
      "part": "snout/nose",
      "looks_like": "long tapered snout with a blunt tip, a single visible nostril, short fine whiskers near the mouth, and small scales on the dorsal surface",
      "where": "forming the anterior-most part of the head, extending to the right"
    },
    {
      "part": "legs",
      "looks_like": "four thick muscular legs, upper portions covered in overlapping dark scales, lower portions with pale pinkish-gray bare skin with some dark speckling/dirt, stout and columnar",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the rear, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "broad feet with thick toes bearing long curved dark brown to black claws, three to four claws visible per foot, pale soles with dirt around the base",
      "where": "at the distal end of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long thick tapering tail, dorsally covered in overlapping scales similar to the body, ventral surface with transverse ridges, tip pointed",
      "where": "extending horizontally to the right from the rear of the body behind the hind legs, resting on the ground"
    },
    {
      "part": "scales/plates",
      "looks_like": "numerous overlapping plate-like keratin scales, dark brown to gray with tan lighter edges and fine radial striations, arranged in diagonal rows",
      "where": "covering the back, sides, top of head, outer forelegs and hindlegs, and dorsal surface of the tail"
    },
    {
      "part": "skin/markings",
      "looks_like": "large irregular patches of pale pink bare skin with soft wrinkles and folds, contrasting sharply with the dark scales, with no hair",
      "where": "one large patch on the mid-dorsal back, one on the mid-flank above the foreleg, and one on the lower rump/upper hindleg and rear flank"
    }
  ],
  "attached_objects": [],
  "animals": [
    "pangolin"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
